#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#ifdef __AVX512F__
#define VW 16
#define MR 12
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5) X(6) X(7) X(8) X(9) X(10) X(11)
#else
#define VW 8
#define MR 6
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5)
#endif
#define NR (2 * VW)
#define KC 256
#define MC 120
#define NC 1024

typedef float vf __attribute__((vector_size(VW * 4)));

static inline vf ldu(const float *p) { vf v; memcpy(&v, p, sizeof v); return v; }
static inline void stu(float *p, vf v) { memcpy(p, &v, sizeof v); }

/* Full MR x NR tile: C (=|+=) Apanel * Bpanel. */
static inline __attribute__((always_inline))
void kernel(int kc, const float *restrict a, const float *restrict b,
            float *restrict c, int ldc, int acc)
{
#define DECL(i) vf c##i##_0 = {0}, c##i##_1 = {0};
    ROWS(DECL)
#undef DECL

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)b;
        vf b1 = *(const vf *)(b + VW);
#define STEP(i) { float t = a[i]; c##i##_0 += t * b0; c##i##_1 += t * b1; }
        ROWS(STEP)
#undef STEP
        a += MR;
        b += NR;
    }

    if (acc) {
#define ACC(i) { float *p = c + (size_t)(i) * ldc; \
                 stu(p, ldu(p) + c##i##_0); stu(p + VW, ldu(p + VW) + c##i##_1); }
        ROWS(ACC)
#undef ACC
    } else {
#define ST(i) { float *p = c + (size_t)(i) * ldc; stu(p, c##i##_0); stu(p + VW, c##i##_1); }
        ROWS(ST)
#undef ST
    }
}

static void kernel_edge(int kc, const float *a, const float *b, float *c, int ldc,
                        int mr, int nr, int acc)
{
    float tmp[MR * NR] __attribute__((aligned(64)));
    kernel(kc, a, b, tmp, NR, 0);
    for (int i = 0; i < mr; i++) {
        float *cp = c + (size_t)i * ldc;
        const float *t = tmp + i * NR;
        if (acc)
            for (int j = 0; j < nr; j++) cp[j] += t[j];
        else
            for (int j = 0; j < nr; j++) cp[j] = t[j];
    }
}

/* Packs an mc x kc block of A into MR-row panels (k-major), zero-padding the last one. */
static void pack_a(const float *A, int n, int i0, int mc, int p0, int kc, float *restrict Ap)
{
    for (int ip = 0; ip < mc; ip += MR) {
        int rows = mc - ip < MR ? mc - ip : MR;
        float *d = Ap + (size_t)ip * kc;
        const float *s = A + (size_t)(i0 + ip) * n + p0;
        if (rows == MR) {
            const float *sp[MR];
            for (int r = 0; r < MR; r++) sp[r] = s + (size_t)r * n;
            for (int k = 0; k < kc; k++) {
#pragma GCC unroll 12
                for (int r = 0; r < MR; r++) d[r] = sp[r][k];
                d += MR;
            }
        } else {
            for (int k = 0; k < kc; k++) {
                int r = 0;
                for (; r < rows; r++) d[r] = s[(size_t)r * n + k];
                for (; r < MR; r++) d[r] = 0.0f;
                d += MR;
            }
        }
    }
}

static void pack_b(const float *B, int n, int p0, int kc, int j0, int nc, float *restrict Bp)
{
    for (int jp = 0; jp < nc; jp += NR) {
        int cols = nc - jp < NR ? nc - jp : NR;
        float *dst = Bp + (size_t)jp * kc;
        for (int k = 0; k < kc; k++) {
            const float *src = B + (size_t)(p0 + k) * n + j0 + jp;
            float *d = dst + k * NR;
            if (cols == NR) {
                memcpy(d, src, NR * sizeof(float));
            } else {
                int j = 0;
                for (; j < cols; j++) d[j] = src[j];
                for (; j < NR; j++) d[j] = 0.0f;
            }
        }
    }
}

typedef struct {
    const float *A, *B;
    float *C;
    int n, r0, r1, tid;
} job_t;

static void naive_rows(const float *A, const float *B, float *C, int n, int r0, int r1)
{
    for (int i = r0; i < r1; i++) {
        float *c = C + (size_t)i * n;
        for (int jj = 0; jj < n; jj++) c[jj] = 0.0f;
        for (int k = 0; k < n; k++) {
            float a = A[(size_t)i * n + k];
            const float *b = B + (size_t)k * n;
            for (int jj = 0; jj < n; jj++) c[jj] += a * b[jj];
        }
    }
}

static void gemm_rows(const float *A, const float *B, float *C, int n, int r0, int r1, int tid)
{
    if (r0 >= r1) return;
    /* Stagger buffers per thread so siblings' panels do not share cache sets. */
    size_t off = (size_t)(tid % 16) * (64 + 1024) / sizeof(float);
    float *Abuf = aligned_alloc(64, sizeof(float) * (MC * KC + 16 * 1088 / 4 + 64));
    float *Bbuf = aligned_alloc(64, sizeof(float) * (KC * NC + 16 * 1088 / 4 + 64));
    if (!Abuf || !Bbuf) {
        free(Abuf); free(Bbuf);
        naive_rows(A, B, C, n, r0, r1);
        return;
    }
    float *Ap = Abuf + off, *Bp = Bbuf + off;

    for (int jc = 0; jc < n; jc += NC) {
        int nc = n - jc < NC ? n - jc : NC;
        int nfull = nc / NR * NR;
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int acc = pc != 0;
            pack_b(B, n, pc, kc, jc, nc, Bp);
            for (int ic = r0; ic < r1; ic += MC) {
                int mc = r1 - ic < MC ? r1 - ic : MC;
                int mfull = mc / MR * MR;
                pack_a(A, n, ic, mc, pc, kc, Ap);
                float *cb = C + (size_t)ic * n + jc;
                for (int jr = 0; jr < nfull; jr += NR) {
                    const float *bp = Bp + (size_t)jr * kc;
                    int ir = 0;
                    for (; ir < mfull; ir += MR)
                        kernel(kc, Ap + (size_t)ir * kc, bp, cb + (size_t)ir * n + jr, n, acc);
                    if (ir < mc)
                        kernel_edge(kc, Ap + (size_t)ir * kc, bp, cb + (size_t)ir * n + jr,
                                    n, mc - ir, NR, acc);
                }
                if (nfull < nc) {
                    const float *bp = Bp + (size_t)nfull * kc;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel_edge(kc, Ap + (size_t)ir * kc, bp, cb + (size_t)ir * n + nfull,
                                    n, mr, nc - nfull, acc);
                    }
                }
            }
        }
    }
    free(Abuf);
    free(Bbuf);
}

static void *worker(void *arg)
{
    job_t *j = arg;
    gemm_rows(j->A, j->B, j->C, j->n, j->r0, j->r1, j->tid);
    return NULL;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    long ncpu = sysconf(_SC_NPROCESSORS_ONLN);
    int nt = ncpu > 0 ? (int)ncpu : 1;
    if (nt > 64) nt = 64;
    if (n < 128) nt = 1;
    int max_by_rows = (n + 24 - 1) / 24;
    if (nt > max_by_rows) nt = max_by_rows;
    if (nt < 1) nt = 1;

    if (nt == 1) {
        gemm_rows(A, B, C, n, 0, n, 0);
        return;
    }

    int chunk = (n + nt - 1) / nt;
    chunk = (chunk + MR - 1) / MR * MR;

    pthread_t th[64];
    job_t jobs[64];
    int created[64];

    for (int t = 0; t < nt; t++) {
        int r0 = t * chunk;
        int r1 = r0 + chunk;
        if (r0 > n) r0 = n;
        if (r1 > n) r1 = n;
        jobs[t] = (job_t){A, B, C, n, r0, r1, t};
        created[t] = 0;
        if (t > 0 && r0 < r1)
            created[t] = pthread_create(&th[t], NULL, worker, &jobs[t]) == 0;
    }

    gemm_rows(A, B, C, n, jobs[0].r0, jobs[0].r1, 0);

    for (int t = 1; t < nt; t++) {
        if (created[t])
            pthread_join(th[t], NULL);
        else
            gemm_rows(A, B, C, n, jobs[t].r0, jobs[t].r1, t);
    }
}
